nextflow_process {

    name "Test Process RESFINDER_RUN"
    script "../main.nf"
    process "RESFINDER_RUN"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "resfinder"
    tag "resfinder/run"

    test("sarscov2 - fastq se") {

        def resfinder_db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            resfinder_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/resfinder.tar.gz').resolve('resfinder')
        }

        when {
            process {
                """

                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ],
                    []
                ]

                input[1] = []

                input[2] = file('${resfinder_db}')
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["json"])
                    ).match() },
            )
        }

    }

    test("sarscov2 - fastq pe") {

        def resfinder_db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            resfinder_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/resfinder.tar.gz').resolve('resfinder')
        }

        when {
            process {
                """

                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ],
                    []
                ]

                input[1] = []

                input[2] = file('${resfinder_db}')
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["json"])
                    ).match() },
            )
        }

    }

    test("sarscov2 - fasta") {

        def resfinder_db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            resfinder_db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/resfinder.tar.gz').resolve('resfinder')
        }

        when {
            process {
                """

                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    [],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                ]

                input[1] = []

                input[2] = file('${resfinder_db}')
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["json", "resfinder_blast"])
                    ).match() },
            )
        }

    }

    test("sarscov2 - fastq - stub") {

        options "-stub"

        when {
            process {
                """

                input[0] = [
                    [ id:'test', single_end:true ], // meta map
                    [],
                    []
                ]

                input[1] = []

                input[2] = []
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() },
            )
        }

    }

}

